 function deleteHolding(hid:string){if(!confirm('Eliminare questo investimento? I movimenti associati saranno conservati.'))return;setData(d=>({...d,holdings:d.holdings.filter(h=>h.id!==hid)}));}
 function applyTransactionToHolding(h:Holding,t:Transaction,sign:1|-1){
  const amount=Number(t.amount)||0, units=Number(t.units)||0;
  let nextUnits=h.units,nextCost=h.costBasis,nextContributed=h.totalContributed;
  if(t.kind==='Versamento'||t.kind==='Acquisto'){nextUnits+=sign*units;nextCost+=sign*amount;if(nextContributed!==undefined)nextContributed+=sign*amount;}
  else if(t.kind==='Rimborso'){const impact=Number((t as any).costImpact)||0;nextUnits-=sign*units;nextCost+=sign*impact;if(nextContributed!==undefined)nextContributed+=sign*impact;}
  else if(t.kind==='Commissione')nextCost+=sign*amount;
  else if(t.kind==='Rettifica'){nextUnits+=sign*units;nextCost+=sign*amount;}
  return {...h,units:Math.max(0,nextUnits),costBasis:Math.max(0,nextCost),totalContributed:nextContributed===undefined?undefined:Math.max(0,nextContributed),updatedAt:new Date().toISOString()};
 }
 function addTransaction(t:Transaction){
  const original=editingTransaction,h=data.holdings.find(x=>x.id===t.holdingId);
  if(!h){setMessage('Errore: investimento non trovato.');return;}
  const amount=Number(t.amount)||0,units=Number(t.units)||0,price=Number(t.price)||0;
  if(!t.date){setMessage('Inserisci la data del movimento.');return;}
  if(t.confirmed&&['Versamento','Acquisto','Rimborso'].includes(t.kind)&&(amount<=0||units<=0||price<=0)){setMessage('Importo, prezzo quota e quote calcolate devono essere maggiori di zero.');return;}
  if(t.confirmed&&t.kind==='Rimborso'&&units>h.units+(original?.units||0)){setMessage('Il rimborso supera le quote disponibili.');return;}
  if(t.confirmed&&t.kind==='Commissione'&&amount<=0){setMessage('La commissione deve avere un importo maggiore di zero.');return;}
  setData(d=>{
   let holdings=d.holdings;
   if(original?.confirmed)holdings=holdings.map(x=>x.id===original.holdingId?applyTransactionToHolding(x,original,-1):x);
   holdings=holdings.map(x=>{
    if(x.id!==t.holdingId||!t.confirmed)return x;
    const tx={...t} as Transaction;
    if(t.kind==='Rimborso'){if(units>x.units+1e-8)return x;(tx as any).costImpact=(x.units>0?x.costBasis/x.units:0)*units;}
    return applyTransactionToHolding(x,tx,1);
   });
   const transactions=original?d.transactions.map(x=>x.id===original.id?t:x):[t,...d.transactions];
   return {...d,transactions,holdings};
  });
  setModal(null);setEditingTransaction(null);setMessage(t.confirmed?'Movimento salvato: quote e capitale aggiornati.':'Movimento pianificato: posizione invariata.');
 }
 function deleteTransaction(t:Transaction){
  if(!confirm('Eliminare questo movimento? La posizione verrà ricalcolata.'))return;
  setData(d=>({...d,holdings:t.confirmed?d.holdings.map(h=>h.id===t.holdingId?applyTransactionToHolding(h,t,-1):h):d.holdings,transactions:d.transactions.filter(x=>x.id!==t.id)}));
  setMessage('Movimento eliminato e posizione aggiornata.');
 }
 function exportData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});download(blob,'personal-wealth-os-backup.json');}
